3	export type Gender = 'male' | 'female' | 'other';
4	export type MaritalStatus = 'never_married' | 'divorced' | 'widowed';
5	export type VerificationStatus = 'pending' | 'verified' | 'failed';
6	export type SubscriptionStatus = 'active' | 'expired' | 'cancelled' | 'inactive';
7	export type FlagStatus = 'open' | 'reviewing' | 'actioned' | 'dismissed';
8	
