13	  phone: string | null;
14	  phone_verified: boolean;
15	  gender: Gender | null;
16	  dob: Date | null;
17	  location: string | null;
18	  lat: number | null;
19	  lng: number | null;
20	  device_id: string | null;
21	  created_at: Date;
22	}
23	
24	export interface ProfileRow {
25	  user_id: string;
26	  name: string | null;
