1	import { BadRequestException, ConflictException, Injectable } from '@nestjs/common';
2	import { Db } from '../db/db';
3	import { FeedCard, UserRow } from '../db/types';
4	import { PushService } from '../notifications/push.service';
5	import { SubscriptionService } from '../subscription/subscription.service';
6	
7	export interface FeedFilters {
8	  minAge?: number;
9	  maxAge?: number;
10	  radiusKm?: number;
11	  limit?: number;
12	  offset?: number;
13	}
14	
15	export interface LikeOutcome {
16	  liked: true;
17	  matched: boolean;
18	  matchId: string | null;
19	  likesRemainingToday: number;
20	}
21	
22	/**
23	 * Feed + interactions. The quota decrement and the candidate query are the two
24	 * pieces of logic the spec calls out as race- and correctness-sensitive, so they
25	 * are kept as literal SQL here rather than built up through the Repo helper.
26	 */
27	@Injectable()
28	export class FeedService {
29	  constructor(
30	    private readonly db: Db,
31	    private readonly push: PushService,
32	    private readonly subscriptions: SubscriptionService,
33	  ) {}
34	
35	  async feed(user: UserRow, f: FeedFilters): Promise<FeedCard[]> {
36	    const limit = Math.min(Math.max(f.limit ?? 20, 1), 50);
37	    const offset = Math.max(f.offset ?? 0, 0);
38	
39	    return this.db.all<FeedCard>(
40	      `WITH me AS (SELECT gender, lat, lng FROM users WHERE id = $1),
41	            mine AS (SELECT interest_id FROM user_interests WHERE user_id = $1),
42	            candidates AS (
43	         SELECT u.id AS user_id, u.gender, u.location,
44	                EXTRACT(YEAR FROM age(u.dob))::int AS age,
45	                p.name, p.bio, p.profession, p.education, p.marital_status, p.photos,
46	                p.verification_status,
47	                (SELECT count(*)::int FROM user_interests x
48	                  WHERE x.user_id = u.id
49	                    AND x.interest_id IN (SELECT interest_id FROM mine)) AS shared_interests,
50	                -- Haversine inline rather than the earthdistance extension: same
51	                -- result, no extension to provision on a managed Postgres.
52	                CASE
53	                  WHEN u.lat IS NULL OR u.lng IS NULL OR $2::float8 IS NULL THEN NULL
54	                  ELSE 6371 * acos(least(1, greatest(-1,
55	                         sin(radians($2::float8)) * sin(radians(u.lat)) +
56	                         cos(radians($2::float8)) * cos(radians(u.lat)) *
57	                         cos(radians(u.lng - $3::float8)))))
58	                END AS distance_km
59	           FROM users u
60	           JOIN profiles p ON p.user_id = u.id
61	          WHERE u.id <> $1
62	            AND u.gender IS NOT NULL
63	            AND u.gender <> (SELECT gender FROM me)
64	            -- Only verified profiles are browsable; re-verification hides a
65	            -- profile again until it resolves (spec 2.3).
66	            AND p.verification_status = 'verified'
67	            AND ($4::int IS NULL OR EXTRACT(YEAR FROM age(u.dob)) >= $4)
68	            AND ($5::int IS NULL OR EXTRACT(YEAR FROM age(u.dob)) <= $5)
69	            -- Spec 2.3: exclude passes and blocks in both directions.
70	            AND NOT EXISTS (SELECT 1 FROM passes  WHERE user_id     = $1 AND passed_user_id = u.id)
71	            AND NOT EXISTS (SELECT 1 FROM blocks  WHERE blocker_id  = $1 AND blocked_id    = u.id)
72	            AND NOT EXISTS (SELECT 1 FROM blocks  WHERE blocked_id  = $1 AND blocker_id    = u.id)
73	            -- An outgoing like is a swipe-past too: never re-serve the card.
74	            AND NOT EXISTS (SELECT 1 FROM likes   WHERE from_user_id = $1 AND to_user_id   = u.id)
75	            AND NOT EXISTS (SELECT 1 FROM matches WHERE (user_a_id = $1 AND user_b_id = u.id)
76	                                                     OR (user_b_id = $1 AND user_a_id = u.id))
77	       )
78	       SELECT * FROM candidates
79	        -- No location on either side means we cannot filter, so we show rather
80	        -- than silently empty the feed.
81	        WHERE ($6::float8 IS NULL OR distance_km IS NULL OR distance_km <= $6::float8)
82	        -- Spec 1.2: ranked by interest-tag overlap. Distance and recency break ties.
83	        ORDER BY shared_interests DESC, distance_km ASC NULLS LAST, user_id
84	        LIMIT $7 OFFSET $8`,
85	      [user.id, user.lat, user.lng, f.minAge ?? null, f.maxAge ?? null, f.radiusKm ?? null, limit, offset],
86	    );
87	  }
88	
89	  /** Spec 2.3 — atomic quota check + decrement, then like and possible match. */
90	  async like(user: UserRow, targetId: string): Promise<LikeOutcome> {
91	    if (user.id === targetId) throw new BadRequestException('cannot_like_self');
92	
93	    const blocked = await this.db.count(
94	      `SELECT count(*)::int AS n FROM blocks
95	        WHERE (blocker_id = $1 AND blocked_id = $2) OR (blocker_id = $2 AND blocked_id = $1)`,
96	      [user.id, targetId],
97	    );
98	    if (blocked) throw new ConflictException('blocked');
99	
100	    const target = await this.db.one<{ id: string }>('SELECT id FROM users WHERE id = $1', [targetId]);
101	    if (!target) throw new BadRequestException('unknown_user');
102	
103	    // A user who has never opened the subscription screen has no row yet, and
104	    // the decrement below would report zero rows as "inactive".
105	    await this.subscriptions.ensure(user.id);
106	
107	    return this.db.tx(async (conn) => {
108	      // Never read-then-write: the WHERE clause is the concurrency control, so a
109	      // double-tap can only ever consume one like.
110	      const decremented = await conn.query(
111	        `UPDATE subscriptions
112	            SET likes_remaining_today = likes_remaining_today - 1
113	          WHERE user_id = $1
114	            AND status = 'active'
115	            AND likes_remaining_today > 0
116	        RETURNING likes_remaining_today`,
117	        [user.id],
118	      );
119	
120	      if (!decremented.rowCount) {
121	        // Zero rows is ambiguous, so ask why once the write has already failed.
122	        const sub = await conn.query(
123	          'SELECT status, likes_remaining_today FROM subscriptions WHERE user_id = $1',
124	          [user.id],
125	        );
126	        const row = sub.rows[0] as { status: string; likes_remaining_today: number } | undefined;
127	        if (!row || row.status !== 'active') throw new ConflictException('subscription_inactive');
128	        throw new ConflictException('no_likes_remaining');
129	      }
130	
131	      await conn.query(
132	        `INSERT INTO likes (from_user_id, to_user_id) VALUES ($1, $2)
133	         ON CONFLICT (from_user_id, to_user_id) DO NOTHING`,
134	        [user.id, targetId],
135	      );
136	
137	      const reciprocal = await conn.query(
138	        'SELECT 1 FROM likes WHERE from_user_id = $2 AND to_user_id = $1',
139	        [user.id, targetId],
140	      );
141	      if (!reciprocal.rowCount) {
142	        const remaining = (decremented.rows[0] as { likes_remaining_today: number }).likes_remaining_today;
143	        // Fire-and-forget outside the transaction would be better once volume
144	        // justifies a queue; inline keeps it simple at MVP.
145	        void this.push.toUser(targetId, 'new_like', { fromUserId: user.id });
146	        return { liked: true, matched: false, matchId: null, likesRemainingToday: remaining };
147	      }
148	
149	      // Pair is stored normalized so the UNIQUE index prevents a duplicate match.
150	      const match = await conn.query(
151	        `INSERT INTO matches (user_a_id, user_b_id)
152	         VALUES (least($1::uuid, $2::uuid), greatest($1::uuid, $2::uuid))
153	         ON CONFLICT (user_a_id, user_b_id) DO UPDATE SET unmatched_at = NULL
154	         RETURNING id`,
155	        [user.id, targetId],
156	      );
157	      const matchId = (match.rows[0] as { id: string }).id;
158	
159	      void this.push.toUser(targetId, 'new_match', { matchId });
160	      void this.push.toUser(user.id, 'new_match', { matchId });
161	
162	      const remaining = (decremented.rows[0] as { likes_remaining_today: number }).likes_remaining_today;
163	      return { liked: true, matched: true, matchId, likesRemainingToday: remaining };
164	    });
165	  }
166	
167	  async pass(user: UserRow, targetId: string): Promise<{ passed: true }> {
168	    if (user.id === targetId) throw new BadRequestException('cannot_pass_self');
169	    await this.db.query(
170	      `INSERT INTO passes (user_id, passed_user_id) VALUES ($1, $2)
171	       ON CONFLICT (user_id, passed_user_id) DO NOTHING`,
172	      [user.id, targetId],
173	    );
174	    return { passed: true };
175	  }
176	
177	  /** Spec 1.2 — block removes the pair from both feeds and ends any match. */
178	  async block(user: UserRow, targetId: string, reason?: string): Promise<{ blocked: true }> {
179	    if (user.id === targetId) throw new BadRequestException('cannot_block_self');
180	    await this.db.tx(async (conn) => {
181	      await conn.query(
182	        `INSERT INTO blocks (blocker_id, blocked_id) VALUES ($1, $2)
183	         ON CONFLICT (blocker_id, blocked_id) DO NOTHING`,
184	        [user.id, targetId],
185	      );
186	      await conn.query(
187	        `UPDATE matches SET unmatched_at = now()
188	          WHERE unmatched_at IS NULL
189	            AND ((user_a_id = $1 AND user_b_id = $2) OR (user_a_id = $2 AND user_b_id = $1))`,
190	        [user.id, targetId],
191	      );
192	      if (reason) {
193	        await conn.query(
194	          'INSERT INTO reports (reporter_id, reported_id, reason) VALUES ($1, $2, $3)',
195	          [user.id, targetId, reason],
196	        );
197	      }
198	    });
199	    return { blocked: true };
200	  }
201	}
