4	import 'api.dart';
5	import 'models.dart';
6	
7	/// ----------------------------------------------------------------- auth
8	
9	final firebaseAuthProvider = Provider<FirebaseAuth>((_) => FirebaseAuth.instance);
10	
11	/// Firebase's own auth stream — the source of truth for signed-in/out.
12	final authStateProvider = StreamProvider<User?>(
13	  (ref) => ref.watch(firebaseAuthProvider).authStateChanges(),
14	);
15	
16	/// ------------------------------------------------------------------ api
17	
18	final apiProvider = Provider<Api>(
19	  (ref) => Api(
20	    token: () async {
21	      // getIdToken() refreshes automatically when the cached token is stale.
22	      final user = ref.read(firebaseAuthProvider).currentUser;
23	      if (user == null) return null;
24	      return user.getIdToken();
25	    },
26	  ),
27	);
28	
29	/// --------------------------------------------------------- repositories
30	
31	/// Generic read-only remote collection. Every list endpoint is one of these,
32	/// so the fetch-and-parse code exists once rather than per resource.
33	class RemoteRepo<T> {
34	  const RemoteRepo(this._api, this._path, this._fromJson, {this.key = 'items'});
35	
36	  final Api _api;
37	  final String _path;
38	  final T Function(Map<String, dynamic>) _fromJson;
39	  final String key;
40	
41	  Future<List<T>> list({Map<String, Object?>? query}) =>
42	      _api.listOf(_path, _fromJson, query: query, key: key);
43	}
44	
45	final matchesRepoProvider = Provider<RemoteRepo<MatchSummary>>(
46	  (ref) => RemoteRepo(ref.watch(apiProvider), '/matches', MatchSummary.fromJson, key: 'matches'),
47	);
48	
49	/// ------------------------------------------------------- async notifier
50	
51	/// Shared lifecycle for every remotely-backed notifier: subclasses supply
52	/// [fetch] and inherit build, refresh and error mapping.
53	abstract class RemoteAsync<T> extends AsyncNotifier<T> {
54	  Api get api => ref.read(apiProvider);
55	
56	  Future<T> fetch(Api api);
57	
58	  @override
59	  Future<T> build() => fetch(api);
60	
61	  /// Re-fetches, surfacing loading then either data or a mapped error.
62	  Future<void> reload() async {
63	    state = const AsyncValue.loading();
64	    state = await AsyncValue.guard(() => fetch(api));
65	  }
66	}
67	
68	/// ------------------------------------------------------------ session
69	
70	class Session {
71	  const Session({required this.signedIn, this.profileComplete = false});
72	
73	  const Session.signedOut() : signedIn = false, profileComplete = false;
74	
75	  final bool signedIn;
76	  final bool profileComplete;
77	}
78	
79	final sessionProvider = AsyncNotifierProvider<SessionNotifier, Session>(SessionNotifier.new);
80	
81	/// Provisions the users row server-side and reports whether onboarding is done.
82	class SessionNotifier extends RemoteAsync<Session> {
83	  @override
84	  Future<Session> fetch(Api api) async {
85	    if (ref.read(firebaseAuthProvider).currentUser == null) return const Session.signedOut();
86	    final json = await api.post<Map<String, dynamic>>('/auth/verify-token');
87	    final onboarding = json['onboarding'] as Map<String, dynamic>? ?? const {};
88	    return Session(
89	      signedIn: true,
90	      profileComplete: onboarding['profileComplete'] as bool? ?? false,
91	    );
92	  }
93	}
94	
95	/// ------------------------------------------------------------ profile
96	
97	final myProfileProvider = AsyncNotifierProvider<MyProfileNotifier, MyProfile>(
98	  MyProfileNotifier.new,
99	);
100	
101	class MyProfileNotifier extends RemoteAsync<MyProfile> {
102	  @override
103	  Future<MyProfile> fetch(Api api) =>
104	      api.get('/profile', (j) => MyProfile.fromJson(j as Map<String, dynamic>));
105	
106	  Future<void> save(Map<String, Object?> body) async {
107	    await api.post('/profile', body: body);
108	    await reload();
109	  }
110	
111	  Future<void> addPhoto(String url, {bool makePrimary = false}) async {
112	    await api.post('/profile/photo', body: {'url': url, 'makePrimary': makePrimary});
113	    await reload();
114	  }
115	}
116	
117	/// Tag catalogue for the interest/language pickers.
118	final tagsProvider = FutureProvider<({List<Tag> interests, List<Tag> languages})>((ref) async {
119	  final api = ref.watch(apiProvider);
120	  return api.get('/profile/interests', (j) {
121	    final map = j as Map<String, dynamic>;
122	    return (
123	      interests: Json.children(map, 'interests', Tag.fromJson),
124	      languages: Json.children(map, 'languages', Tag.fromJson),
125	    );
126	  });
127	});
128	
129	/// ------------------------------------------------------- verification
130	
131	final verificationProvider =
132	    AsyncNotifierProvider<VerificationNotifier, VerificationStatus>(VerificationNotifier.new);
133	
134	class VerificationNotifier extends RemoteAsync<VerificationStatus> {
135	  @override
