import { BadRequestException, Injectable } from '@nestjs/common';
import { Db } from '../db/db';
import { ProfileRow, TagRow, UserRow } from '../db/types';
import { ModerationService } from '../moderation/moderation.service';
import { VerificationService } from '../verification/verification.service';

const MAX_PHOTOS = 6;

export interface ProfileInput {
  name: string;
  gender: 'male' | 'female' | 'other';
  dob: string;
  location?: string;
  lat?: number;
  lng?: number;
  bio?: string;
  education?: string;
  profession?: string;
  maritalStatus?: 'never_married' | 'divorced' | 'widowed';
  interestIds?: number[];
  languageIds?: number[];
}

@Injectable()
export class ProfileService {
  constructor(
    private readonly db: Db,
    private readonly moderation: ModerationService,
    private readonly verification: VerificationService,
  ) {}

  interests(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('interests').all('SELECT id, label FROM interests ORDER BY label');
  }

  languages(): Promise<TagRow[]> {
    return this.db.repo<TagRow>('languages').all('SELECT id, label FROM languages ORDER BY label');
  }

  async upsert(user: UserRow, dto: ProfileInput) {
    const bio = dto.bio ?? '';
    const screening = await this.moderation.screenText(bio, user.id, 'bio', user.id);

    try {
      await this.db.tx(async (conn) => {
        // The users_min_age trigger rejects dob under 18 here regardless of what
        // the client sent — spec 2.3, server-side age enforcement.
        await conn.query(
          `UPDATE users SET gender = $2, dob = $3, location = $4, lat = $5, lng = $6 WHERE id = $1`,
          [user.id, dto.gender, dto.dob, dto.location ?? null, dto.lat ?? null, dto.lng ?? null],
        );

        await conn.query(
          `INSERT INTO profiles (user_id, name, bio, education, profession, marital_status, bio_flagged)
           VALUES ($1, $2, $3, $4, $5, $6, $7)
           ON CONFLICT (user_id) DO UPDATE SET
             name = EXCLUDED.name,
             bio = EXCLUDED.bio,
             education = EXCLUDED.education,
             profession = EXCLUDED.profession,

content.content:
50	          [user.id, dto.gender, dto.dob, dto.location ?? null, dto.lat ?? null, dto.lng ?? null],
51	        );
52	
53	        await conn.query(
54	          `INSERT INTO profiles (user_id, name, bio, education, profession, marital_status, bio_flagged)
55	           VALUES ($1, $2, $3, $4, $5, $6, $7)
56	           ON CONFLICT (user_id) DO UPDATE SET
57	             name = EXCLUDED.name,
58	             bio = EXCLUDED.bio,
59	             education = EXCLUDED.education,
60	             profession = EXCLUDED.profession,
61	             marital_status = EXCLUDED.marital_status,
62	             bio_flagged = EXCLUDED.bio_flagged,
63	             updated_at = now()`,
64	          [
65	            user.id,
66	            dto.name,
67	            bio,
68	            dto.education ?? null,
69	            dto.profession ?? null,
70	            dto.maritalStatus ?? null,
71	            screening.flagged,
72	          ],
73	        );
74	
75	        await this.replaceTags(conn, 'user_interests', 'interest_id', user.id, dto.interestIds);
76	        await this.replaceTags(conn, 'user_languages', 'language_id', user.id, dto.languageIds);
77	      });
78	    } catch (err) {
79	      if ((err as { message?: string }).message?.includes('under_min_age')) {
80	        throw new BadRequestException('under_min_age');
81	      }
82	      throw err;
83	    }
84	
85	    return this.me(user.id);
86	  }
87	
88	  /**
89	   * Spec 1.2 — photos arrive pre-uploaded to storage by the client; this endpoint
90	   * records the URL, screens it, and re-opens verification when it is primary.
91	   */
92	  async addPhoto(userId: string, url: string, makePrimary?: boolean) {
93	    const existing = await this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]);
94	    const photos = existing?.photos ?? [];
95	
96	    if (!existing) {
97	      await this.db.query('INSERT INTO profiles (user_id) VALUES ($1)', [userId]);
98	    }
99	    if (photos.length >= MAX_PHOTOS) throw new BadRequestException('photo_limit_reached');
100	
101	    const isPrimary = makePrimary ?? photos.length === 0;
102	    const previousPrimary = photos[0];
103	    const next = isPrimary ? [url, ...photos] : [...photos, url];
104	
105	    await this.moderation.screenImage(userId, url, `${userId}:${next.length}`);
106	    await this.db.query('UPDATE profiles SET photos = $2, updated_at = now() WHERE user_id = $1', [
107	      userId,
108	      next,
109	    ]);
110	
111	    // The trigger already reset verification_status to 'pending'; this records
112	    // the audit event that the pending screen and review queue read.
113	    if (isPrimary && previousPrimary !== url) {
114	      await this.verification.reopen(userId, previousPrimary ? 'primary_photo_changed' : 'initial_photo');
115	    }
116	
117	    return { photos: next, primaryPhoto: next[0], reVerificationRequired: isPrimary };
118	  }
119	
120	  async me(userId: string) {
121	    const [user, profile, interests, languages] = await Promise.all([
122	      this.db.one<UserRow>(
123	        'SELECT id, email, phone, phone_verified, gender, dob, location, lat, lng, created_at FROM users WHERE id = $1',
124	        [userId],
125	      ),
126	      this.db.one<ProfileRow>('SELECT * FROM profiles WHERE user_id = $1', [userId]),
127	      this.db.repo<TagRow>('interests').all(
128	        `SELECT i.id, i.label FROM interests i
129	         JOIN user_interests ui ON ui.interest_id = i.id WHERE ui.user_id = $1 ORDER BY i.label`,
130	        [userId],
131	      ),
132	      this.db.repo<TagRow>('languages').all(
133	        `SELECT l.id, l.label FROM languages l
134	         JOIN user_languages ul ON ul.language_id = l.id WHERE ul.user_id = $1 ORDER BY l.label`,
135	        [userId],
136	      ),
137	    ]);
138	
