             name = EXCLUDED.name,
             bio = EXCLUDED.bio,
             education = EXCLUDED.education,
             profession = EXCLUDED.profession,
             marital_status = EXCLUDED.marital_status,
             bio_flagged = EXCLUDED.bio_flagged,
