  location?: string;
  lat?: number;
  lng?: number;
  bio?: string;
  education?: string;
  profession?: string;
  maritalStatus?: 'never_married' | 'divorced' | 'widowed';
  interestIds?: number[];
  languageIds?: number[];
}

