    const user = await this.users.require(principal.uid);
    return this.profiles.me(user.id);
  }

  @Post()
  async save(@Auth() principal: Principal, @Body() dto: ProfileDto) {
    const user = await this.users.require(principal.uid);
    return this.profiles.upsert(user, dto);
